INSERT INTO users (name, email)
VALUES ('Ann', 'ann@example.com')
RETURNING id;

CREATE TABLE sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

SELECT department, ARRAY_AGG(name ORDER BY name) AS people
FROM employees
GROUP BY department;

SELECT data->>'email' AS email, data->'address'->>'city' AS city
FROM profiles
WHERE data ? 'email';

WITH recent AS (
  SELECT * FROM orders WHERE created_at > now() - interval '30 days'
), totals AS (
  SELECT user_id, SUM(total) AS spent FROM recent GROUP BY user_id
)
SELECT u.name, t.spent FROM totals t JOIN users u ON u.id = t.user_id;

CREATE OR REPLACE FUNCTION touch_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE tags (
  id SERIAL PRIMARY KEY,
  label TEXT NOT NULL UNIQUE
);

SELECT COALESCE(nickname, name) AS shown,
       created_at::date AS joined
FROM users;

SELECT COUNT(*) FILTER (WHERE status = 'paid') AS paid,
       COUNT(*) FILTER (WHERE status = 'open') AS open
FROM invoices;
